import{_ as d,o as a,a as _,b as e}from"./app.UgfkfLuP.js";const c="/ascendc.github.io/assets/atlas_a2_a3_architecture.BP01tdr0.png",r="/ascendc.github.io/assets/npu_3510_hw_arch_sync.DwGkFw4L.png",i=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"数据搬运导览","link":"/api/SIMD-API/c_api/data_move_guide/data_move_guide"},{"text":"概览","link":"/api/SIMD-API/c_api/data_move_guide/overview/overview"},{"text":"数据通路","link":"/api/SIMD-API/c_api/data_move_guide/overview/data_path"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/data_move_guide/overview/data_path.md","filePath":"api/SIMD-API/c_api/data_move_guide/overview/data_path.md","outlineHeaders":[{"level":2,"title":"AI Core硬件架构与存储单元","slug":"AI-Core硬件架构与存储单元","link":"#AI-Core硬件架构与存储单元"},{"level":3,"title":"存储单元用途","slug":"存储单元用途","link":"#存储单元用途"},{"level":2,"title":"数据通路与搬运流水","slug":"数据通路与搬运流水","link":"#数据通路与搬运流水"}],"lastUpdated":1790563388000}'),o={name:"api/SIMD-API/c_api/data_move_guide/overview/data_path.md"};function l(p,t,s,m,f,u){return a(),_("div",null,[...t[0]||(t[0]=[e('<div><article class="markdown-body"><h1>数据通路</h1><h2 id="AI-Core硬件架构与存储单元">AI Core硬件架构与存储单元<a class="header-anchor" href="#AI-Core硬件架构与存储单元">​</a></h2><p>AI Core采用分层存储架构。计算单元包括Cube、Vector和Scalar；存储单元包括Global Memory（GM）、L1 Buffer、L0A/L0B/L0C Buffer、Unified Buffer（UB）、BiasTable Buffer、Fixpipe Buffer和SIMD Register File；MTE1、MTE2、MTE3和Fixpipe负责在不同存储单元之间传输数据。</p><p>图1给出<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构版本2201</a>的存储和搬运通路，便于理解AI Core各存储层级的基本关系。</p><p><strong>图1</strong> NPU架构版本2201下的AI Core硬件架构</p><p><img src="'+c+'" alt="NPU架构版本2201下的AI Core硬件架构" title="NPU架构版本2201下的AI Core硬件架构"></p><p><a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构版本3510</a>的内部结构如图2所示。与图1相比，数据通路主要有以下变化：</p><ul><li>新增L0C Buffer到UB的单向数据通路。</li><li>新增UB到L1 Buffer的数据通路。</li><li>不再提供GM到L0A/L0B的直达通路，矩阵输入需要先搬到L1 Buffer。</li><li>不再提供L1 Buffer到GM的直达通路。</li><li>AIV增加SIMD Register File，Vector Function通过Reg加载、存储接口与UB交换数据。</li></ul><p><strong>图2</strong> NPU架构版本3510下的AI Core硬件架构与同步关系</p><p><img src="'+r+'" alt="NPU架构版本3510下的AI Core硬件架构与同步关系" title="NPU架构版本3510下的AI Core硬件架构与同步关系"></p><p>本导览后续接口选择均以Ascend 950PR&amp;950DT系列产品（NPU架构版本3510）为准。其他产品的数据通路和接口支持情况应以对应接口文档的产品支持表为准。</p><h3 id="存储单元用途">存储单元用途<a class="header-anchor" href="#存储单元用途">​</a></h3><table><thead><tr><th>存储单元</th><th>C API地址空间或对象</th><th>主要用途</th></tr></thead><tbody><tr><td>GM</td><td><code>__gm__</code></td><td>保存Kernel输入、输出以及跨核共享数据。</td></tr><tr><td>L1 Buffer</td><td><code>__cbuf__</code></td><td>缓存Cube输入，也是GM与L0A/L0B之间的中转存储。</td></tr><tr><td>L0A Buffer</td><td><code>__ca__</code></td><td>保存矩阵计算的左矩阵输入。</td></tr><tr><td>L0B Buffer</td><td><code>__cb__</code></td><td>保存矩阵计算的右矩阵输入。</td></tr><tr><td>L0C Buffer</td><td><code>__cc__</code></td><td>保存矩阵计算累加结果。</td></tr><tr><td>UB</td><td><code>__ubuf__</code></td><td>保存Vector输入、输出和中间结果，并作为AIC与AIV交换数据的片上存储。</td></tr><tr><td>BiasTable Buffer</td><td>以<code>uint64_t</code>目的地址传入</td><td>保存Mmad使用的bias。</td></tr><tr><td>Fixpipe Buffer</td><td><code>__fbuf__</code></td><td>保存L0C搬出使用的随路Vector量化和随路ReLU参数。</td></tr><tr><td>SIMD Register File</td><td><code>vector_*</code>、<code>vector_bool</code>等<a href="../../defs/type/reg_data_types.html">寄存器类型</a></td><td>保存Vector Function使用的矢量数据、掩码和地址状态。</td></tr></tbody></table><h2 id="数据通路与搬运流水">数据通路与搬运流水<a class="header-anchor" href="#数据通路与搬运流水">​</a></h2><p>下表按源、目的存储单元列出NPU架构版本3510可用的数据搬运功能。每行对应一种可直接选择的C接口形态；同一接口具有多个重载时，按功能分别列出。</p><p><strong>表1</strong> NPU架构版本3510数据搬运功能总览</p><table><thead><tr><th>源（SRC）</th><th>目的（DST）</th><th>流水</th><th>功能</th><th>C API</th></tr></thead><tbody><tr><td>GM</td><td>L1 Buffer</td><td>PIPE_MTE2</td><td>连续搬运；配置一个数据块，源、目的步长设为0</td><td><a href="../../cube_datamove/asc_copy_gm2l1/asc_copy_gm2l1_highdim_split_arch_3510.html">asc_copy_gm2l1</a></td></tr><tr><td>GM</td><td>L1 Buffer</td><td>PIPE_MTE2</td><td>高维切分搬运；通过数据块个数、块长和源/目的步长描述排布</td><td><a href="../../cube_datamove/asc_copy_gm2l1/asc_copy_gm2l1_highdim_split_arch_3510.html">asc_copy_gm2l1</a></td></tr><tr><td>GM</td><td>L1 Buffer</td><td>PIPE_MTE2</td><td>以512字节分形为单位执行二维矩阵搬运</td><td><a href="../../cube_datamove/asc_copy_gm2l1/asc_copy_gm2l1_2d_arch_3510.html">asc_copy_gm2l1</a></td></tr><tr><td>GM</td><td>L1 Buffer</td><td>PIPE_MTE2</td><td>搬运时将ND数据转换为Nz排布</td><td><a href="../../cube_datamove/asc_copy_gm2l1_nd2nz/asc_copy_gm2l1_nd2nz_arch_3510.html">asc_copy_gm2l1_nd2nz</a></td></tr><tr><td>GM</td><td>L1 Buffer</td><td>PIPE_MTE2</td><td>搬运时将DN数据转换为Nz排布</td><td><a href="../../cube_datamove/asc_copy_gm2l1_dn2nz.html">asc_copy_gm2l1_dn2nz</a></td></tr><tr><td>GM</td><td>L1 Buffer</td><td>PIPE_MTE2</td><td>非对齐搬运，支持Compact、Normal、左右Padding和循环填充</td><td><a href="../../cube_datamove/asc_copy_gm2l1_align.html">asc_copy_gm2l1_align</a></td></tr><tr><td>L0C Buffer</td><td>GM</td><td>PIPE_FIX</td><td>搬出矩阵结果，可组合量化、激活、Nz2ND/Nz2DN和通道处理</td><td><a href="../../cube_datamove/asc_copy_l0c2gm/asc_copy_l0c2gm_arch_3510.html">asc_copy_l0c2gm</a></td></tr><tr><td>GM</td><td>UB</td><td>PIPE_MTE2</td><td>连续搬运</td><td><a href="../../vector_datamove/asc_copy_gm2ub/asc_copy_gm2ub_arch_3510.html">asc_copy_gm2ub</a></td></tr><tr><td>GM</td><td>UB</td><td>PIPE_MTE2</td><td>高维切分搬运</td><td><a href="../../vector_datamove/asc_copy_gm2ub/asc_copy_gm2ub_arch_3510.html">asc_copy_gm2ub</a></td></tr><tr><td>GM</td><td>UB</td><td>PIPE_MTE2</td><td>非对齐连续搬运，目的端补齐到32字节边界</td><td><a href="../../vector_datamove/asc_copy_gm2ub_align/asc_copy_gm2ub_align_arch_3510.html">asc_copy_gm2ub_align</a></td></tr><tr><td>GM</td><td>UB</td><td>PIPE_MTE2</td><td>非对齐高维切分搬运，支持Compact、Normal和左右Padding</td><td><a href="../../vector_datamove/asc_copy_gm2ub_align/asc_copy_gm2ub_align_arch_3510.html">asc_copy_gm2ub_align</a></td></tr><tr><td>GM</td><td>UB</td><td>PIPE_MTE2</td><td>最多五维的Padding或多维数据搬运</td><td><a href="../../vector_datamove/asc_ndim_copy_gm2ub.html">asc_ndim_copy_gm2ub</a></td></tr><tr><td>GM</td><td>UB</td><td>PIPE_MTE2</td><td>通过多维步长组合实现Transpose、Broadcast或Slice</td><td><a href="../../vector_datamove/asc_ndim_copy_gm2ub.html">asc_ndim_copy_gm2ub</a></td></tr><tr><td>UB</td><td>GM</td><td>PIPE_MTE3</td><td>连续搬运</td><td><a href="../../vector_datamove/asc_copy_ub2gm/asc_copy_ub2gm_arch_3510.html">asc_copy_ub2gm</a></td></tr><tr><td>UB</td><td>GM</td><td>PIPE_MTE3</td><td>高维切分搬运</td><td><a href="../../vector_datamove/asc_copy_ub2gm/asc_copy_ub2gm_arch_3510.html">asc_copy_ub2gm</a></td></tr><tr><td>UB</td><td>GM</td><td>PIPE_MTE3</td><td>非对齐连续搬运，写入GM时丢弃补齐数据</td><td><a href="../../vector_datamove/asc_copy_ub2gm_align/asc_copy_ub2gm_align_arch_3510.html">asc_copy_ub2gm_align</a></td></tr><tr><td>UB</td><td>GM</td><td>PIPE_MTE3</td><td>非对齐高维切分搬运，支持Compact和Normal源排布</td><td><a href="../../vector_datamove/asc_copy_ub2gm_align/asc_copy_ub2gm_align_arch_3510.html">asc_copy_ub2gm_align</a></td></tr><tr><td>UB</td><td>L1 Buffer</td><td>PIPE_MTE3</td><td>连续搬运</td><td><a href="../../vector_datamove/asc_copy_ub2l1.html">asc_copy_ub2l1</a></td></tr><tr><td>UB</td><td>L1 Buffer</td><td>PIPE_MTE3</td><td>高维切分搬运</td><td><a href="../../vector_datamove/asc_copy_ub2l1.html">asc_copy_ub2l1</a></td></tr><tr><td>L1 Buffer</td><td>UB</td><td>PIPE_MTE1</td><td>连续搬运，可指定目的AIV</td><td><a href="../../cube_datamove/asc_copy_l12ub.html">asc_copy_l12ub</a></td></tr><tr><td>L1 Buffer</td><td>UB</td><td>PIPE_MTE1</td><td>高维切分搬运，可指定目的AIV</td><td><a href="../../cube_datamove/asc_copy_l12ub.html">asc_copy_l12ub</a></td></tr><tr><td>L1 Buffer</td><td>L0A Buffer</td><td>PIPE_MTE1</td><td>二维分形矩阵搬运</td><td><a href="../../cube_datamove/asc_copy_l12l0a/asc_copy_l12l0a_2d_arch_3510.html">asc_copy_l12l0a</a></td></tr><tr><td>L1 Buffer</td><td>L0A Buffer</td><td>PIPE_MTE1</td><td>二维分形矩阵伴转置搬运</td><td><a href="../../cube_datamove/asc_copy_l12l0a/asc_copy_l12l0a_2d_arch_3510.html">asc_copy_l12l0a_transpose</a></td></tr><tr><td>L1 Buffer</td><td>L0A Buffer</td><td>PIPE_MTE1</td><td>三维img2col搬运，支持Feature Map、Filter、Padding和Repeat配置</td><td><a href="../../cube_datamove/asc_copy_l12l0a/asc_copy_l12l0a_3d_arch_3510.html">asc_copy_l12l0a</a></td></tr><tr><td>L1 Buffer</td><td>L0A_MX Buffer</td><td>PIPE_MTE1</td><td>搬运MX矩阵计算使用的左矩阵量化系数</td><td><a href="../../cube_datamove/asc_copy_l12l0a_mx.html">asc_copy_l12l0a_mx</a></td></tr><tr><td>L1 Buffer</td><td>L0B Buffer</td><td>PIPE_MTE1</td><td>二维分形矩阵搬运</td><td><a href="../../cube_datamove/asc_copy_l12l0b/asc_copy_l12l0b_2d_arch_3510.html">asc_copy_l12l0b</a></td></tr><tr><td>L1 Buffer</td><td>L0B Buffer</td><td>PIPE_MTE1</td><td>二维分形矩阵伴转置搬运</td><td><a href="../../cube_datamove/asc_copy_l12l0b/asc_copy_l12l0b_2d_arch_3510.html">asc_copy_l12l0b_transpose</a></td></tr><tr><td>L1 Buffer</td><td>L0B Buffer</td><td>PIPE_MTE1</td><td>三维img2col搬运，搬运时自动转置</td><td><a href="../../cube_datamove/asc_copy_l12l0b/asc_copy_l12l0b_3d_arch_3510.html">asc_copy_l12l0b</a></td></tr><tr><td>L1 Buffer</td><td>L0B Buffer</td><td>PIPE_MTE1</td><td>按Repeat和分形间隔执行二维分形转置</td><td><a href="../../cube_datamove/asc_copy_l12l0b_trans/asc_copy_l12l0b_trans_arch_3510.html">asc_copy_l12l0b_trans</a></td></tr><tr><td>L1 Buffer</td><td>L0B_MX Buffer</td><td>PIPE_MTE1</td><td>搬运MX矩阵计算使用的右矩阵量化系数</td><td><a href="../../cube_datamove/asc_copy_l12l0b_mx.html">asc_copy_l12l0b_mx</a></td></tr><tr><td>L0C Buffer</td><td>L1 Buffer</td><td>PIPE_FIX</td><td>搬出矩阵结果，可组合量化、激活和格式转换</td><td><a href="../../cube_datamove/asc_copy_l0c2l1/asc_copy_l0c2l1_arch_3510.html">asc_copy_l0c2l1</a></td></tr><tr><td>L0C Buffer</td><td>UB</td><td>PIPE_FIX</td><td>搬出矩阵结果，可组合量化、激活、格式转换和双目标搬运</td><td><a href="../../cube_datamove/asc_copy_l0c2ub.html">asc_copy_l0c2ub</a></td></tr><tr><td>L1 Buffer</td><td>BiasTable Buffer</td><td>PIPE_MTE1</td><td>连续bias搬运，可执行<code>half</code>/<code>bfloat16_t</code>到32位数据的处理</td><td><a href="../../cube_datamove/asc_copy_l12bt/asc_copy_l12bt_arch_3510.html">asc_copy_l12bt</a></td></tr><tr><td>L1 Buffer</td><td>BiasTable Buffer</td><td>PIPE_MTE1</td><td>高维切分bias搬运</td><td><a href="../../cube_datamove/asc_copy_l12bt/asc_copy_l12bt_arch_3510.html">asc_copy_l12bt</a></td></tr><tr><td>L1 Buffer</td><td>Fixpipe Buffer</td><td>PIPE_FIX</td><td>连续搬运量化或ReLU参数</td><td><a href="../../cube_datamove/asc_copy_l12fb/asc_copy_l12fb_arch_3510.html">asc_copy_l12fb</a></td></tr><tr><td>L1 Buffer</td><td>Fixpipe Buffer</td><td>PIPE_FIX</td><td>高维切分搬运量化或ReLU参数</td><td><a href="../../cube_datamove/asc_copy_l12fb/asc_copy_l12fb_arch_3510.html">asc_copy_l12fb</a></td></tr><tr><td>UB</td><td>UB</td><td>PIPE_V</td><td>连续复制</td><td><a href="../../vector_datamove/asc_copy_ub2ub.html">asc_copy_ub2ub</a></td></tr><tr><td>UB</td><td>UB</td><td>PIPE_V</td><td>高维切分复制</td><td><a href="../../vector_datamove/asc_copy_ub2ub.html">asc_copy_ub2ub</a></td></tr><tr><td>UB</td><td>SIMD Register File</td><td>Vector Function</td><td>对齐、非对齐、广播或掩码加载</td><td><a href="../../reg_compute/load/reg_load_overview.html">Reg数据搬入</a></td></tr><tr><td>SIMD Register File</td><td>UB</td><td>Vector Function</td><td>对齐、非对齐或掩码存储</td><td><a href="../../reg_compute/store/reg_store_overview.html">Reg数据搬出</a></td></tr></tbody></table><p>NPU架构版本3510不支持GM到L0A/L0B直达搬运，数据需要经过GM到L1 Buffer、L1 Buffer到L0两段通路；也不支持L1 Buffer到GM或UB到L0C的通用直达搬运。接口名称在多个NPU架构间相同时，也不能据此推断NPU架构版本3510支持该接口，应以接口文档中的产品支持情况为准。</p><p>各通路的模式、参数单位和关键约束请继续阅读<a href="../data_move_guide.html">数据搬运导览</a>中的对应章节。硬件存储结构的完整说明请参见<a href="../../../../../guide/programming_guide/advanced_programming/hardware_implementation/architecture_spec/npu_arch_3510.html">NPU架构版本3510硬件规格</a>。</p></article></div>',1)])])}const b=d(o,[["render",l]]);export{i as __pageData,b as default};
